{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have an aws_s3_bucket_public_access_block resource associated with it, leaving the default public access settings potentially enabled or unmanaged."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Access logging is not configured for this S3 bucket, which prevents tracking of requests made to the bucket and hinders security auditing."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "example" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "example" {
  bucket = aws_s3_bucket.b.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "my-tf-log-bucket-ggff"
  acl    = "log-delivery-write"
}",
  "fix_summary": "Added an aws_s3_bucket_public_access_block resource to enforce strict public access controls. Added an aws_s3_bucket_logging resource pointing to a newly created dedicated log bucket to enable access logging as required by CKV_AWS_18."
}
